<?php declare(strict_types=1);require_once __DIR__.'/../../../bootstrap/app.php';use App\Services\Auth;use App\Services\TruckService;Auth::requirePermission('TRUCK_VIEW_OWN');$id=(int)($_GET['id']??0);$t=TruckService::findOwn($id);if(!$t){http_response_code(404);exit('Truck not found.');}$pageTitle='Truck '.$t['registration_number'];require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><h1><?=h($t['registration_number'])?></h1><p><?=h($t['make_name'].' '.$t['model_name'].' · '.$t['manufacture_year'])?></p></div><span class="badge"><?=h(ucfirst($t['verification_status']))?></span></div><?php if(isset($_GET['created'])):?><div class="success">Truck submitted for Operations verification.</div><?php endif;if($t['case_status']==='rejected'):?><div class="error"><strong>Verification rejected.</strong><?php if($t['findings']):?><br><?=nl2br(h($t['findings']))?><?php endif;?></div><?php elseif($t['case_status']==='approved'):?><div class="success">Compliance references verified. Availability remains unavailable until later subscription, driver, and eligibility checks.</div><?php else:?><div class="notice">Verification is pending. The truck cannot be made available.</div><?php endif;?><div class="grid"><div class="card"><h3>Truck</h3><p><?=h(str_replace('_',' ',$t['body_type_code']))?></p><p><?=h($t['capacity_value'].' '.$t['capacity_unit'])?></p><p>Chassis: <?=h($t['chassis_number'])?></p></div><div class="card"><h3>Insurance</h3><p><?=h($t['provider_name'].' · '.$t['policy_number'])?></p><p><?=h($t['coverage_type'])?></p><p><?=h($t['insurance_valid_from'].' – '.$t['insurance_valid_to'])?></p></div><div class="card"><h3>Inspection</h3><p><?=h($t['inspection_number'])?></p><p><?=h($t['result_code'].' · '.$t['roadworthiness_status'])?></p><p>Expires <?=h($t['inspection_expires_on'])?></p></div></div><?php require BASE_PATH.'/app/Views/layout/footer.php';
